#include <stdio.h>
#include <string.h>

int main(void)
{
    FILE *f = tmpfile();
    if (f == NULL) {
        return 1;
    }
    fputs("A B\n", f);
    rewind(f);
    char line[8];
    if (fgets(line, sizeof line, f) == NULL) {
        fclose(f);
        return 1;
    }
    printf("%zu\n", strlen(line));
    fclose(f);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    const char *s = "  two\twords ";
    int words = 0;
    int inside = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        int space = isspace((unsigned char)s[i]);
        if (!space && !inside) {
            words++;
        }
        inside = !space;
    }
    printf("%d\n", words);
    return 0;
}

